using System;
using Comfort.Common;
using EFT;
using EFT.Vehicle;
using HarmonyLib;
using UnityEngine;
namespace LocalSpt5Esp;
internal static partial class TeleportControl {
 static Vector2 markerScroll;static Vector3? marker,nativeMarker;static string markerSource="";static IntPtr markedWorld;
 internal static void InitializeMarkers(Plugin plugin){try{plugin.Patches.Patch(AccessTools.Method(typeof(BotGroupRequestController),"TryAddRequest"),prefix:new HarmonyMethod(typeof(TeleportControl),nameof(ObserveRequest)));plugin.Patches.Patch(AccessTools.Method(typeof(BotGroupRequestController),"TryAddRequestByPlayer"),prefix:new HarmonyMethod(typeof(TeleportControl),nameof(ObservePlayerRequest)));}catch(Exception e){plugin.Log.LogWarning("Player point observation: "+e.Message);}}
 static void ObserveRequest(BotRequest __0){try{var request=__0?.TryCast<GoToPointRequest>();var current=Singleton<GameWorld>.Instance;if(!RaidClock.Active||current?.MainPlayer is not {} local||request?.Requester?.ProfileId!=local.ProfileId)return;Tick(current);nativeMarker=request.Position;}catch(Exception e){Plugin.Self.Log.LogWarning("Player point: "+e.Message);}}
 static void ObservePlayerRequest(IPlayer __0,BotRequest __1)=>ObserveRequest(__1);
 static void ResetMarkers(){marker=nativeMarker=null;markedWorld=IntPtr.Zero;markerSource="";}
 static void Mark(Vector3 point,string source){var current=Current();if(!TeleportRules.Finite(new(point.x,point.y,point.z)))throw new ArgumentException("标记坐标无效。");marker=point;markerSource=source;markedWorld=current.Pointer;notice="已设置标记："+source+" · "+point.ToString("F1");FeatureToasts.Show(notice);}
 static void PickMarker(){var current=Current();var camera=Camera.main??throw new ArgumentException("当前相机未就绪。");int mask=LayerMask.GetMask("HighPolyCollider","Terrain","LowPolyCollider");if(mask==0||!Physics.Raycast(camera.transform.position,camera.transform.forward,out var hit,2000,mask,QueryTriggerInteraction.Ignore)||hit.normal.y<.45f)throw new ArgumentException("请将准星对准有效地面后重新标记。");Mark(hit.point,"准星地面");}
 static Vector3 RequireMarker(){if(marker is not Vector3 point||Current().Pointer!=markedWorld)throw new ArgumentException("先在当前战局放置标记点。");return point;}
 static bool TryBtr(out Vector3 point,out string name){point=default;name="BTR";var current=Singleton<GameWorld>.Instance;if(!RaidClock.Active||current?.Pointer!=world)return false;var controller=current.BtrController;var view=controller?.BtrView;if(view==null||!view.gameObject.activeInHierarchy||view.RouteState==EVehicleRouteState.OnDepot)return false;point=view.transform.position+view.transform.right*6;name="BTR · "+(view.BtrState is EBtrState.Stop or EBtrState.StopPaid?"停靠中":"行驶中");return true;}
 static void SaveMarker(){var point=RequireMarker();x=point.x.ToString("G9",System.Globalization.CultureInfo.InvariantCulture);y=point.y.ToString("G9",System.Globalization.CultureInfo.InvariantCulture);z=point.z.ToString("G9",System.Globalization.CultureInfo.InvariantCulture);pointMap=Map;pointName="标记 · "+markerSource;editId="";SavePoint(true);}
 static void DrawMarkerPage(Rect rect){float height=Math.Max(rect.height-1,480);markerScroll=GUI.BeginScrollView(rect,markerScroll,new Rect(0,0,rect.width-20,height));DrawMarkerContents(new Rect(0,0,rect.width-20,height));GUI.EndScrollView();}
 static void DrawMarkerContents(Rect rect){float x=rect.x,y=rect.y,w=rect.width,half=(w-12)/2;if(InterfaceMenu.Button(new Rect(x,y,half,36),marker.HasValue?"重新用准星放置标记":"准星对准地面后放置标记"))Action(PickMarker);if(InterfaceMenu.Button(new Rect(x+half+12,y,half,36),"清除标记")){marker=null;markedWorld=IntPtr.Zero;notice="标记点已清除。";}y+=52;if(InterfaceMenu.Button(new Rect(x,y,half,34),"使用 AI 生成页选点"))Action(()=>{if(!AiTestControl.TrySpawnPoint(out var point))throw new ArgumentException("先在 AI 生成页完成地面选点。");Mark(point,"AI 生成选点");});if(InterfaceMenu.Button(new Rect(x+half+12,y,half,34),"使用最近游戏报点"))Action(()=>Mark(nativeMarker??throw new ArgumentException("先在游戏中发出带位置的前进指令，才能读取报点。"),"游戏前进报点"));y+=52;InterfaceMenu.Paragraph(new Rect(x,y,w,80),marker is Vector3 position?"标记："+markerSource+" · "+position.ToString("F2")+"\n距玩家 "+Vector3.Distance(Current().MainPlayer.Position,position).ToString("F1")+" 米 · 将移动 "+(useAiSources?sources.Count+" 名所选 AI":"玩家"):"尚未放置标记。先对准地面放置，或使用已有选点。",InterfaceMenu.Accent,14);y+=100;bool old=GUI.enabled;GUI.enabled=old&&marker.HasValue&&(!useAiSources||sources.Count>0);if(InterfaceMenu.Button(new Rect(x,y,half,40),useAiSources?"所选 AI 传送到标记点":"玩家传送到标记点"))Action(()=>Execute(new("marker","玩家标记点","",RequireMarker(),Mark:true)));if(InterfaceMenu.Button(new Rect(x+half+12,y,half,40),"收藏这个标记点"))Action(SaveMarker);GUI.enabled=old;y+=58;InterfaceMenu.Paragraph(new Rect(x,y,w,70),"多名 AI 会分开放置，并检查可站立地面。标记只在当前战局有效，收藏后可长期保存。BTR 可在上方单独选择；传送到车辆侧面附近。",null,12);InterfaceMenu.Paragraph(new Rect(x,rect.yMax-60,w,58),notice,InterfaceMenu.Accent,12);}
 internal static void DrawPlayerMarker(Camera camera,Player local){if(marker is not Vector3 point||!RaidClock.Active||Singleton<GameWorld>.Instance?.Pointer!=markedWorld)return;RaidLoot.DrawMarker(camera,point+Vector3.up*.15f,"传送标记 · "+markerSource,Vector3.Distance(local.Position,point),new Color(.3f,1,.8f),false);}
}
